function roundHalfEven(x, decimals=2){
  const factor = Math.pow(10,decimals);
  const scaled = x*factor;
  const floor = Math.floor(scaled);
  const diff = scaled-floor;
  const eps=1e-9;
  let rounded;
  if (Math.abs(diff-0.5)<eps){
    rounded = (floor%2===0)?floor:floor+1;
  } else {
    rounded = Math.round(scaled);
  }
  return rounded/factor;
}

let subtotal = 409.70;
let frete = 12.00 + 2.00*1.8;
frete = roundHalfEven(frete);
console.log("frete", frete);

let totalPedido = subtotal - 0 + frete + 0; // imposto guess 0
console.log("totalPedido", totalPedido);
let n=6, taxa=0.0199;
let fator = 1-Math.pow(1+taxa,-n);
let parcelaRaw = totalPedido*taxa/fator;
console.log("parcela raw", parcelaRaw);
let parcelaR = roundHalfEven(parcelaRaw);
console.log("parcela rounded", parcelaR);
let totalFinal = parcelaR*n;
totalFinal = Math.round(totalFinal*100)/100;
console.log("totalFinal", totalFinal);
console.log("ajuste", roundHalfEven(totalFinal-totalPedido));
EOF

