        FormaPagamento formaPagamento = parseEnum(FormaPagamento.class, request.formaPagamento(), CodigoErro.FORMA_PAGAMENTO_INVALIDA);
        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
