function r(x){
  // half-even round to 2 decimals, x is number but use string-based precision via toFixed tricks
  const factor=100;
  const scaled = x*factor;
  const floor = Math.floor(scaled + 1e-9);
  const diff = scaled - floor;
  let rounded;
  if (Math.abs(diff-0.5) < 1e-6){
    rounded = (floor % 2 === 0) ? floor : floor+1;
  } else {
    rounded = Math.round(scaled);
  }
  return rounded/factor;
}

